// Pseudo-code: fetch per-tenant feature flags
import { AppConfigurationClient } from "@azure/app-configuration";

async function getFeatures(req) {
  const tenant = (req.headers["x-tenant-id"] || "").trim();
  const env = process.env.ENV || "dev";
  const client = new AppConfigurationClient(process.env.APPCONFIG_CONNECTION_STRING);
  const setting = await client.getConfigurationSetting({ key: "featureFlags", label: `${tenant}--${env}` });
  return JSON.parse(setting.value);
}
```

